<!DOCTYPE html><html lang="vi"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Phân quyền cán bộ</title><link rel="stylesheet" href="/css/professional-form.css"><style>body{margin:0;background:#E9EAE8;font-family:'Times New Roman',Times,serif}.shell{max-width:900px;margin:30px auto;background:#fff;border:1px solid #d6d8d6;border-top:5px solid #b91c1c;border-radius:12px;padding:24px}.shell h1{color:#a31515}.row{display:grid;grid-template-columns:220px 1fr auto;gap:16px;align-items:center;border-bottom:1px solid #e2e4e2;padding:18px 0}.row strong{font-size:18px}.row p{margin:4px 0;color:#666}.toggle{border:0;border-radius:999px;padding:10px 16px;color:#fff;font-weight:700;cursor:pointer}.bat{background:#18794e}.tat{background:#777}.back{float:right;color:#a31515;text-decoration:none;font-weight:700}@media(max-width:760px){.row{grid-template-columns:1fr}.toggle{justify-self:start}}</style></head><body><div class="shell"><a class="back" href="/quan_tri/tong_quan">← Dashboard</a><h1>Phân quyền nghiệp vụ cán bộ</h1><p>Mỗi quyền được quản lý độc lập và có hiệu lực cho lần truy cập tiếp theo.</p>
<?php $items=[['quan_ly_ho_so','Quản lý hồ sơ công dân','Tra cứu, xem và quản lý hồ sơ căn cước'],['duyet_dieu_chinh','Duyệt yêu cầu điều chỉnh','Xem, phê duyệt hoặc từ chối yêu cầu điều chỉnh'],['quan_ly_trang_thai','Quản lý trạng thái thẻ','Tiếp nhận và xử lý yêu cầu liên quan trạng thái thẻ']]; foreach($items as $item): ?>
<div class="row"><div><strong><?php echo e($item[1]); ?></strong><p><?php echo e($item[2]); ?></p></div><div><span>Trạng thái: <strong><?php echo !empty($quyen[$item[0]])?'Đang bật':'Đang tắt'; ?></strong></span></div><form method="POST"><input type="hidden" name="ma_csrf" value="<?php echo e(taoMaCsrf()); ?>"><input type="hidden" name="quyen" value="<?php echo e($item[0]); ?>"><input type="hidden" name="bat" value="<?php echo !empty($quyen[$item[0]])?'0':'1'; ?>"><button class="toggle <?php echo !empty($quyen[$item[0]])?'tat':'bat'; ?>"><?php echo !empty($quyen[$item[0]])?'Tắt quyền':'Bật quyền'; ?></button></form></div>
<?php endforeach; ?></div></body></html>
